const ok = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));
const no = (ms, v) => new Promise((_, r) => setTimeout(() => r(new Error(v)), ms));

// A
await Promise.all([no(10, 'x'), ok(50, 'b')]);
// B
await Promise.allSettled([no(10, 'x'), ok(50, 'b')]);
// C
await Promise.race([no(10, 'x'), ok(50, 'b')]);
// D
await Promise.any([no(10, 'x'), ok(50, 'b')]);

For each: does it fulfill or reject, what is the value/reason, and at roughly what time?

